-- ═══════════════════════════════════════════════════════════
-- BATCH 1: Migrations (colunas novas em Customers e Orders)
-- ═══════════════════════════════════════════════════════════
IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='Customers' AND COLUMN_NAME='cep')
  ALTER TABLE Customers ADD cep NVARCHAR(9) NULL;
IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='Customers' AND COLUMN_NAME='street')
  ALTER TABLE Customers ADD street NVARCHAR(200) NULL;
IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='Customers' AND COLUMN_NAME='number')
  ALTER TABLE Customers ADD [number] NVARCHAR(20) NULL;
IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='Customers' AND COLUMN_NAME='complement')
  ALTER TABLE Customers ADD complement NVARCHAR(200) NULL;
IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='Customers' AND COLUMN_NAME='neighborhood')
  ALTER TABLE Customers ADD neighborhood NVARCHAR(200) NULL;
IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='Customers' AND COLUMN_NAME='city')
  ALTER TABLE Customers ADD city NVARCHAR(100) NULL;
IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='Customers' AND COLUMN_NAME='uf')
  ALTER TABLE Customers ADD uf NVARCHAR(2) NULL;
IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='Customers' AND COLUMN_NAME='latitude')
  ALTER TABLE Customers ADD latitude DECIMAL(9,6) NULL;
IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='Customers' AND COLUMN_NAME='longitude')
  ALTER TABLE Customers ADD longitude DECIMAL(9,6) NULL;
IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='Orders' AND COLUMN_NAME='deliveryFee')
  ALTER TABLE Orders ADD deliveryFee DECIMAL(10,2) NOT NULL DEFAULT 0;
IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='Orders' AND COLUMN_NAME='channel')
  ALTER TABLE Orders ADD channel NVARCHAR(50) NOT NULL DEFAULT 'balcao';
IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME='Orders' AND COLUMN_NAME='deliveredAt')
  ALTER TABLE Orders ADD deliveredAt DATETIME2 NULL;

GO
