DECLARE @bid UNIQUEIDENTIFIER = '6c17daca-ef47-4cb7-b4e4-fc6230d1372c';

-- ─── LIMPAR ───────────────────────────────────────────────
DELETE FROM OrderItemVariations
WHERE orderItemId IN (
  SELECT oi.id FROM OrderItems oi
  INNER JOIN Orders o ON oi.orderId = o.id
  WHERE o.businessId = @bid
);
DELETE FROM OrderItems WHERE orderId IN (SELECT id FROM Orders WHERE businessId = @bid);
DELETE FROM Orders    WHERE businessId = @bid;
DELETE FROM Customers WHERE businessId = @bid;
DELETE FROM Products  WHERE businessId = @bid;

