SELECT NEWID(), o.id,
  CASE (o.id % 20)
    WHEN 0  THEN @p1  WHEN 1  THEN @p3  WHEN 2  THEN @p5  WHEN 3  THEN @p2
    WHEN 4  THEN @p7  WHEN 5  THEN @p4  WHEN 6  THEN @p6  WHEN 7  THEN @p8
    WHEN 8  THEN @p10 WHEN 9  THEN @p3  WHEN 10 THEN @p1  WHEN 11 THEN @p5
    WHEN 12 THEN @p14 WHEN 13 THEN @p7  WHEN 14 THEN @p2  WHEN 15 THEN @p6
    WHEN 16 THEN @p17 WHEN 17 THEN @p4  WHEN 18 THEN @p3  ELSE    @p1
  END,
  1,
  CASE (o.id % 20)
    WHEN 0  THEN 51.00 WHEN 1  THEN 66.00 WHEN 2  THEN 60.00 WHEN 3  THEN 52.00
    WHEN 4  THEN 55.00 WHEN 5  THEN 57.00 WHEN 6  THEN 76.00 WHEN 7  THEN 58.00
    WHEN 8  THEN 56.00 WHEN 9  THEN 66.00 WHEN 10 THEN 51.00 WHEN 11 THEN 60.00
    WHEN 12 THEN 55.00 WHEN 13 THEN 55.00 WHEN 14 THEN 52.00 WHEN 15 THEN 76.00
    WHEN 16 THEN 12.00 WHEN 17 THEN 57.00 WHEN 18 THEN 66.00 ELSE   51.00
  END,
  CASE (o.id % 20)
    WHEN 0  THEN 51.00 WHEN 1  THEN 66.00 WHEN 2  THEN 60.00 WHEN 3  THEN 52.00
    WHEN 4  THEN 55.00 WHEN 5  THEN 57.00 WHEN 6  THEN 76.00 WHEN 7  THEN 58.00
    WHEN 8  THEN 56.00 WHEN 9  THEN 66.00 WHEN 10 THEN 51.00 WHEN 11 THEN 60.00
    WHEN 12 THEN 55.00 WHEN 13 THEN 55.00 WHEN 14 THEN 52.00 WHEN 15 THEN 76.00
    WHEN 16 THEN 12.00 WHEN 17 THEN 57.00 WHEN 18 THEN 66.00 ELSE   51.00
  END
FROM Orders o
WHERE o.businessId = @bid;

-- Segundo item (bebida) para pedidos maiores
INSERT INTO OrderItems (id, orderId, productId, quantity, unitPrice, finalPrice)
SELECT NEWID(), o.id, @p17, 1, 12.00, 12.00
FROM Orders o
WHERE o.businessId = @bid AND o.total > 90 AND o.total < 140;

-- ─── VERIFICAÇÃO ──────────────────────────────────────────
SELECT 'Produtos'  AS tabela, COUNT(*) AS total FROM Products  WHERE businessId = @bid
UNION ALL
SELECT 'Clientes',                               COUNT(*)       FROM Customers WHERE businessId = @bid
UNION ALL
SELECT 'Pedidos',                                COUNT(*)       FROM Orders    WHERE businessId = @bid
UNION ALL
SELECT 'Itens',                                  COUNT(*)       FROM OrderItems WHERE orderId IN (SELECT id FROM Orders WHERE businessId = @bid);
